from collections import defaultdict

# Animals that can act as subjects in existential rules.
A = ['bee', 'frog', 'snake', 'seahorse', 'swan', 'stork', 'beetle', 'finch', 'woodpecker', 'flamingo']
PRIMARY = {'red', 'green', 'blue'}   # RGB primary-color convention from the source domain
SUBMITTED = 'disproved'

# Background assumption: spinach is a leafy green vegetable (needed for Rule21).
F = {
    ('card', 'bee', 'blue'): True,
    ('card', 'frog', 'yellow'): True,
    ('has', 'frog', 'spinach'): True,
    ('leafy', 'spinach', None): True,
    ('tears', 'bee', 'badger'): False,            # bee does not tear down badger's castle
    ('works_fewer', 'snake', None): True,         # snake reduced work hours
    ('creates_vampire', 'seahorse', 'vampire'): False,
}

# (preferred rule, overridden rule)
PREF = {('R11', 'R21'), ('R15', 'R1'), ('R16', 'R21'), ('R24', 'R6'),
        ('R3', 'R22'), ('R8', 'R13'), ('R9', 'R14')}


def exists(s, pred, obj):
    # Existential antecedent: some animal in the universe is proved to satisfy pred(x, obj).
    return any(s.get((pred, x, obj)) is True for x in A)


def rules(s):
    out = []

    def add(key, val, name):
        out.append((key, val, name))

    for x in A:
        if s.get(('shouts', x, 'beaver')) is True:
            add(('unites', x, 'ostrich'), True, 'R1')
        if s.get(('creates_dragon', x, 'dragon')) is True:
            add(('refuses', x, 'dinosaur'), True, 'R8')
        if s.get(('creates_vampire', x, 'vampire')) is False:
            add(('enjoys', x, 'ant'), True, 'R12')
        if s.get(('tears', x, 'badger')) is False:
            add(('refuses', x, 'badger'), True, 'R5')
        if s.get(('refuses', x, 'badger')) is True:
            add(('shouts', x, 'dragonfly'), True, 'R19')
        if s.get(('shouts', x, 'dragonfly')) is True:
            add(('wants', x, 'fangtooth'), True, 'R20')
        if s.get(('wants', x, 'fangtooth')) is True:
            add(('shouts', x, 'beetle'), False, 'R14')
        if s.get(('refuses', x, 'dinosaur')) is False:
            add(('reveals', x, 'zebra'), True, 'R17')
        if s.get(('shouts', x, 'beetle')) is False and s.get(('reveals', x, 'zebra')) is True:
            add(('trades', x, 'stork'), False, 'R18')
        if s.get(('shouts', x, 'peafowl')) is True:
            add(('shouts', x, 'beaver'), True, 'R22')

    if exists(s, 'tears', 'dove'):
        add(('takes', 'woodpecker', 'monkey'), True, 'R2')
    if exists(s, 'persuades', 'rhino'):
        add(('shouts', 'swan', 'beaver'), False, 'R3')
    if s.get(('trades', 'bee', 'stork')) is False and s.get(('trades', 'beetle', 'stork')) is True:
        add(('wants', 'stork', 'goat'), True, 'R4')
    if exists(s, 'enjoys', 'ant'):
        add(('shouts', 'swan', 'peafowl'), False, 'R6')
    if exists(s, 'unites', 'ostrich'):
        add(('trades', 'beetle', 'stork'), True, 'R7')
    if s.get(('smiles', 'flamingo', 'bee')) is True:
        add(('shouts', 'bee', 'beetle'), True, 'R9')
    if exists(s, 'wants', 'goat'):
        add(('captures', 'finch', 'king_pigeon'), False, 'R10')
    if s.get(('age_lt4', 'frog', None)) is True:
        add(('destroys', 'frog', 'swan'), False, 'R11')
    if exists(s, 'takes', 'monkey'):
        add(('refuses', 'bee', 'dinosaur'), False, 'R13')
    if exists(s, 'trades', 'bison'):
        add(('unites', 'swan', 'ostrich'), False, 'R15')
    if any(s.get(('card', 'frog', c)) is True for c in PRIMARY):
        add(('destroys', 'frog', 'swan'), False, 'R16')
    if s.get(('has', 'frog', 'spinach')) is True and s.get(('leafy', 'spinach', None)) is True:
        add(('destroys', 'frog', 'swan'), True, 'R21')
    if s.get(('works_fewer', 'snake', None)) is True:
        add(('tears', 'snake', 'dove'), True, 'R23')
    if s.get(('destroys', 'frog', 'swan')) is True:
        add(('shouts', 'swan', 'peafowl'), True, 'R24')
    return out


def resolve(lst):
    trues = {n for v, n in lst if v is True}
    falses = {n for v, n in lst if v is False}
    if trues and not falses:
        return True
    if falses and not trues:
        return False
    if trues and all(any((t, f) in PREF for t in trues) for f in falses):
        return True
    if falses and all(any((f, t) in PREF for f in falses) for t in trues):
        return False
    return None  # unresolved conflict: not proved either way


# Forward chaining to a fixpoint; only proved literals are used as antecedents.
state = {}
for _ in range(50):
    cands = defaultdict(list)
    for k, v in F.items():
        cands[k].append((v, 'FACT'))
    for key, val, name in rules(state):
        cands[key].append((val, name))
    new = {}
    for key, lst in cands.items():
        r = resolve(lst)
        if r is not None:
            new[key] = r
    if new == state:
        break
    state = new

target = ('captures', 'finch', 'king_pigeon')
for k in [('wants', 'stork', 'goat'), ('trades', 'bee', 'stork'),
          ('trades', 'beetle', 'stork'), ('shouts', 'swan', 'peafowl'),
          ('shouts', 'bee', 'beetle'), ('reveals', 'bee', 'zebra'), target]:
    print(k, '=', state.get(k, 'unproved'))

v = state.get(target)
computed = 'proved' if v is True else ('disproved' if v is False else 'unknown')
print('computed answer:', computed)
print('CHECK PASS' if computed == SUBMITTED else 'CHECK FAIL')
