# Options encoded as booleans: does the explanation "Confucius refrained from
# out-of-season vegetables" stay meaningful when the assumption is false?
# Premise: an abstention is an act of choice, so it requires an available alternative.

def explanation_holds(can_choose_seasonal_or_not):
    # The explanation needs a choice between seasonal and out-of-season vegetables.
    return can_choose_seasonal_or_not

options = {
    "A": {"assumption": "Confucius is very demanding about diet", "necessary": False},
    "B": {"assumption": "Both seasonal and out-of-season vegetables existed in his era", "necessary": False},
    "C": {"assumption": "We can choose to eat seasonal or out-of-season vegetables", "necessary": True},
}

# Necessity test: if the assumption is false, the explanation fails.
necessary = []
for key, opt in options.items():
    assumption_true = opt["necessary"]
    if explanation_holds(assumption_true) and not explanation_holds(not assumption_true):
        necessary.append(key)

final = necessary[0] if len(necessary) == 1 else "UNSUPPORTED"

print(json.dumps({
    "final_answer": final,
    "evidence": {
        "necessary_options": necessary,
        "rule": "abstaining from out-of-season vegetables presupposes a choice between seasonal and out-of-season vegetables"
    }
}, separators=(",", ":")))
