import json

def prime_factors(n):
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        factors.append(n)
    return factors

def is_prime(k):
    if k < 2:
        return False
    d = 2
    while d * d <= k:
        if k % d == 0:
            return False
        d += 1
    return True

N = 33146799
factors = prime_factors(N)

product = 1
for p in factors:
    product *= p

checks = {
    "product_matches": product == N,
    "all_prime": all(is_prime(p) for p in factors),
    "sorted_nondecreasing": all(factors[i] <= factors[i + 1] for i in range(len(factors) - 1)),
}

if all(checks.values()):
    final_answer = ", ".join(str(p) for p in factors)
else:
    final_answer = "UNSUPPORTED"

result = {
    "final_answer": final_answer,
    "evidence": {
        "n": N,
        "prime_factors_with_multiplicity": factors,
        "distinct_prime_factors": sorted(set(factors)),
        "product_of_factors": product,
        "checks": checks,
    },
}

print(json.dumps(result, separators=(",", ":")))
