PAIRS = {')': '(', ']': '[', '}': '{', '>': '<'}
OPENERS = set(PAIRS.values())
CLOSER_FOR = {v: k for k, v in PAIRS.items()}

INPUT = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ]"
SUBMITTED = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ] ) ] ) ]"


def scan(tokens):
    """Return (open_stack_bottom_to_top, error). error is None if no mismatch, underflow, or bad token."""
    stack = []
    for i, t in enumerate(tokens):
        if t in OPENERS:
            stack.append(t)
        elif t in PAIRS:
            if not stack:
                return stack, ("unmatched closer", i, t)
            top = stack.pop()
            if top != PAIRS[t]:
                return stack, ("mismatch", i, t, top)
        else:
            return stack, ("bad token", i, t)
    return stack, None


inp = INPUT.split()
sub = SUBMITTED.split()

in_stack, in_err = scan(inp)
print("input open stack (bottom->top):", in_stack)
print("input error:", in_err)

if in_err is not None:
    print("UNSUPPORTED")
else:
    expected_suffix = [CLOSER_FOR[t] for t in reversed(in_stack)]
    print("expected minimal completion:", " ".join(expected_suffix))

    is_prefix = sub[:len(inp)] == inp
    print("submitted starts with input:", is_prefix)
    print("submitted completion:", " ".join(sub[len(inp):]))

    exp_full = inp + expected_suffix
    e_stack, e_err = scan(exp_full)
    print("expected full: open stack =", e_stack, "error =", e_err)

    s_stack, s_err = scan(sub)
    print("submitted full: open stack =", s_stack, "error =", s_err,
          "error_index =", s_err[1] if s_err else None)

    if is_prefix and sub == exp_full and e_err is None and e_stack == []:
        print("CHECK PASS")
    else:
        print("CHECK FAIL")
